-- phase223 KB (2026-10-23): validation wording -- only tasks without a review need validating.
insert into kb_entry_versions (entry_id, title, content, edited_by) select id, title, content, updated_by from kb_entries where article_number in (33,7,6,10,32,15);
update kb_entries set content = replace(content, $o$Tempo records today as the completion date, and there's nothing to validate.$o$, $n$Tempo records today as the completion date. Work checked by a review or sign-off needs no separate validation; tasks with no review are validated by your supervisor as before.$n$), updated_at = now(), updated_by = 'e7e52a30-4c13-449b-889d-280dc0ca16c6' where article_number = 33;
update kb_entries set content = replace(content, $o${warning:Older projects only} Validation applies to projects created before 13 Oct 2026. On new L&D projects, finishing a task (Mark Done, Ready for Review, Pass QA or Approve) records today as the completion date and there's nothing to validate. See [[October 23 Release]].$o$, $n${accent:New projects} On new L&D projects, work that goes through a review or sign-off is validated by that step, so it won't appear here. Tasks with no review after them (for example a Discovery Call) are still validated as described below. See [[October 23 Release]].$n$), updated_at = now(), updated_by = 'e7e52a30-4c13-449b-889d-280dc0ca16c6' where article_number = 7;
update kb_entries set content = replace(content, $o${accent:New projects} Tasks are validated automatically when they're finished, so the validation check below only applies to older projects.$o$, $n${accent:New projects} Work that goes through a review or sign-off is validated by that step. Tasks with no review still need validating before the project can close.$n$), updated_at = now(), updated_by = 'e7e52a30-4c13-449b-889d-280dc0ca16c6' where article_number = 6;
update kb_entries set content = replace(content, $o${accent:New projects} Reported Completion, Validated date, Validated By and the Validation grouping apply to older projects. On new projects a task's completion date is recorded automatically when it's finished, with no separate validation.$o$, $n${accent:New projects} The completion date is recorded automatically when a task is finished. Work checked by a review or sign-off is validated by that step; other tasks use Validated date and Validated By as usual.$n$), updated_at = now(), updated_by = 'e7e52a30-4c13-449b-889d-280dc0ca16c6' where article_number = 10;
update kb_entries set content = replace(content, $o${warning:Older projects only} New projects skip validation: finishing a task records the date and validates it automatically.$o$, $n${accent:New projects} Work checked by a review or sign-off is validated by that step. Tasks with no review follow the rules below.$n$), updated_at = now(), updated_by = 'e7e52a30-4c13-449b-889d-280dc0ca16c6' where article_number = 32;
update kb_entries set content = replace(content, $o${accent:Note} Validation counts come from older projects only; tasks on new projects are validated automatically when they're finished.$o$, $n${accent:Note} On new projects, only tasks with no review or sign-off after them need validating, so they're the only new-project tasks counted here.$n$), updated_at = now(), updated_by = 'e7e52a30-4c13-449b-889d-280dc0ca16c6' where article_number = 15;
select string_agg(article_number || ':' || (position('review or sign-off' in content) > 0)::text, ' ') from kb_entries where article_number in (33,7,6,10,32,15);
